script.setup:
// Three.js renders into the scene's own WebGL2 context: a field of instanced
// columns rippling like a sound wave, lit by an environment map and a key light.
const mod = await ctx.utils.import("https://esm.sh/three@0.186.0");
const THREE = mod.default ?? mod;
const { RoomEnvironment } = await ctx.utils.import("https://esm.sh/three@0.186.0/examples/jsm/environments/RoomEnvironment.js");
const renderer = new THREE.WebGLRenderer({ canvas: ctx.canvas, context: ctx.gl, antialias: true });
renderer.setPixelRatio(1);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
const scene = new THREE.Scene();
const bg = new THREE.Color(0x07080d);
scene.background = bg;
scene.fog = new THREE.Fog(bg, 18, 42);
const pmrem = new THREE.PMREMGenerator(renderer);
const envMap = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
scene.environment = envMap;
scene.environmentIntensity = 0.2;
const key = new THREE.DirectionalLight(0xfff1e0, 2.2);
key.position.set(8, 14, 6);
key.castShadow = true;
key.shadow.mapSize.set(2048, 2048);
Object.assign(key.shadow.camera, { left: -14, right: 14, top: 14, bottom: -14, near: 1, far: 40 });
scene.add(key);
const N = 34, gap = 0.62;
const geo = new THREE.BoxGeometry(0.5, 1, 0.5);
geo.translate(0, 0.5, 0);
const mat = new THREE.MeshStandardMaterial({ metalness: 0.35, roughness: 0.3 });
const mesh = new THREE.InstancedMesh(geo, mat, N * N);
mesh.castShadow = mesh.receiveShadow = true;
mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
scene.add(mesh);
const floor = new THREE.Mesh(new THREE.PlaneGeometry(80, 80), new THREE.MeshStandardMaterial({ color: 0x0c0e16, roughness: 0.9 }));
floor.rotation.x = -Math.PI / 2;
floor.receiveShadow = true;
scene.add(floor);
const camera = new THREE.PerspectiveCamera(40, 1, 0.1, 100);
Object.assign(ctx.state, {
  THREE, renderer, scene, mesh, camera, envMap, pmrem, N, gap, size: [0, 0],
  dummy: new THREE.Object3D(), color: new THREE.Color(), a: new THREE.Color(), b: new THREE.Color(),
  orbit: ctx.utils.createOrbitCamera({ distance: 27, theta: 0.7, phi: 1.08 }),
});

script.render:
const s = ctx.state, u = ctx.uniforms, [w, h] = ctx.resolution;
if (s.size[0] !== w || s.size[1] !== h) {
  s.size = [w, h];
  s.renderer.setSize(w, h, false);
  s.camera.aspect = w / h;
  s.camera.updateProjectionMatrix();
}
s.orbit.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
s.camera.position.fromArray(s.orbit.getEye());
s.camera.lookAt(0, 0, 0);
// Control colors are sRGB; three works in linear space.
s.a.setRGB(...u.u_low, s.THREE.SRGBColorSpace); s.b.setRGB(...u.u_high, s.THREE.SRGBColorSpace);
const t = ctx.time * u.u_speed, half = (s.N - 1) / 2;
for (let i = 0; i < s.N; i++) for (let j = 0; j < s.N; j++) {
  const x = (i - half) * s.gap, z = (j - half) * s.gap, r = Math.hypot(x, z);
  // Two interfering ripples: one from the center, one drifting around it.
  const ox = 5 * Math.cos(t * 0.37), oz = 5 * Math.sin(t * 0.37);
  const wave = Math.sin(r * 0.9 - t * 2.2) * Math.exp(-r * 0.05) + 0.6 * Math.sin(Math.hypot(x - ox, z - oz) * 1.3 - t * 3.1);
  const k = Math.max(0, Math.min(1, wave * 0.32 + 0.5));
  s.dummy.position.set(x, 0, z);
  s.dummy.scale.set(1, 0.15 + u.u_height * k * k, 1);
  s.dummy.updateMatrix();
  const id = i * s.N + j;
  s.mesh.setMatrixAt(id, s.dummy.matrix);
  s.mesh.setColorAt(id, s.color.copy(s.a).lerp(s.b, k * k));
}
s.mesh.instanceMatrix.needsUpdate = true;
s.mesh.instanceColor.needsUpdate = true;
// The runtime touched GL state since the last frame; three caches it, so resync first.
s.renderer.resetState();
s.renderer.render(s.scene, s.camera);
